//! `sj migrate`: replace OpenSpec, Spec Kit and Superpowers in a project with specjutsu.
//!
//! [`plan`] computes every effect without writing; [`apply`] performs the same plan in a fixed
//! order. Removals are explicit: paths named here, listed in a Spec Kit manifest, or proven
//! generated by OpenSpec's own metadata.

mod config_yaml;

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use serde::{Deserialize, Serialize};
use sj_adapters::agents;
use sj_adapters::claude::Change;
use sj_adapters::superpowers;

use crate::authoring::validate::{self, Report};
use crate::config::{self, Config, FILE};
use crate::git::Git;
use crate::import::speckit::{self, Content};
use crate::{adopt, doctor, ids};

pub use config_yaml::to_principles;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Tool {
    OpenSpec,
    SpecKit,
    Superpowers,
}

impl Tool {
    pub const ALL: [Tool; 3] = [Tool::OpenSpec, Tool::SpecKit, Tool::Superpowers];

    pub fn as_str(self) -> &'static str {
        match self {
            Tool::OpenSpec => "openspec",
            Tool::SpecKit => "speckit",
            Tool::Superpowers => "superpowers",
        }
    }

    pub fn parse(s: &str) -> Option<Tool> {
        Tool::ALL.into_iter().find(|t| t.as_str() == s)
    }
}

/// Everything a migration does. `lines` is the preview, in apply order.
pub struct Plan {
    pub tools: Vec<Tool>,
    pub lines: Vec<String>,
    spec_root: PathBuf,
    adopt: Option<Config>,
    prefixes: BTreeMap<String, String>,
    /// `specjutsu.toml` with the pinned prefixes spliced in, when the project has one.
    config_text: Option<String>,
    import: Option<speckit::Plan>,
    assign_ids: bool,
    principles: Option<(PathBuf, String)>,
    /// Files removed one by one, then the folders to prune when left empty.
    remove_files: Vec<PathBuf>,
    /// Folders removed whole.
    remove_dirs: Vec<PathBuf>,
    prune: Vec<PathBuf>,
    settings: Option<(PathBuf, String)>,
    /// The adapters installed last: Claude plus the agents the project has files for.
    agents: Vec<String>,
}

fn rel(p: &Path, root: &Path) -> String {
    p.strip_prefix(root)
        .unwrap_or(p)
        .to_string_lossy()
        .replace('\\', "/")
}

fn plural(n: usize, word: &str) -> String {
    if n == 1 {
        format!("1 {word}")
    } else {
        format!("{n} {word}s")
    }
}

/// The YAML frontmatter lines of a Markdown file, or none.
fn frontmatter(text: &str) -> Vec<&str> {
    let mut lines = text.lines();
    if lines.next().map(str::trim_end) != Some("---") {
        return Vec::new();
    }
    lines.take_while(|l| l.trim_end() != "---").collect()
}

fn field<'a>(front: &[&'a str], key: &str) -> Option<&'a str> {
    front.iter().find_map(|l| {
        let (k, v) = l.trim().split_once(':')?;
        (k == key).then(|| v.trim().trim_matches(['"', '\'']))
    })
}

/// A skill OpenSpec generated: `author: openspec` and a `generatedBy` line.
fn is_openspec_skill(text: &str) -> bool {
    let front = frontmatter(text);
    field(&front, "author") == Some("openspec") && field(&front, "generatedBy").is_some()
}

/// An Antigravity workflow OpenSpec generated: frontmatter holding only `description`, and a
/// body that runs the `openspec` CLI.
fn is_openspec_workflow(text: &str) -> bool {
    let front = frontmatter(text);
    let keys: Vec<&str> = front
        .iter()
        .filter(|l| !l.starts_with([' ', '\t']) && !l.trim().is_empty())
        .filter_map(|l| l.split_once(':').map(|(k, _)| k.trim()))
        .collect();
    if keys != ["description"] {
        return false;
    }
    let body = text.splitn(3, "---").nth(2).unwrap_or("");
    body.contains("`openspec ")
        || body
            .lines()
            .any(|l| l.trim_start().starts_with("openspec "))
}

/// A command OpenSpec generated: `name: "OPSX: <Workflow>"`.
fn is_openspec_command(text: &str) -> bool {
    field(&frontmatter(text), "name").is_some_and(|n| n.starts_with("OPSX:"))
}

fn sorted_entries(dir: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = std::fs::read_dir(dir)
        .map(|d| d.filter_map(|e| e.ok().map(|e| e.path())).collect())
        .unwrap_or_default();
    v.sort();
    v
}

/// Top-level agent folders: every dot-folder but `.git`.
fn agent_dirs(root: &Path) -> Vec<PathBuf> {
    sorted_entries(root)
        .into_iter()
        .filter(|p| p.is_dir())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with('.') && n != ".git")
        })
        .collect()
}

fn files_under(dir: &Path, out: &mut Vec<PathBuf>) {
    for p in sorted_entries(dir) {
        if p.is_dir() {
            files_under(&p, out);
        } else {
            out.push(p);
        }
    }
}

/// The parents of `path` below `root`, deepest first.
fn parents(path: &Path, root: &Path) -> Vec<PathBuf> {
    path.ancestors()
        .skip(1)
        .take_while(|a| *a != root && a.starts_with(root))
        .map(Path::to_path_buf)
        .collect()
}

/// Paths of a clean check: `git status` lines, empty when clean.
fn dirty(root: &Path) -> Result<Vec<String>> {
    let git = Git::new(root);
    if !git.is_repo() {
        bail!(
            "{} is not a git work tree; migrate needs git for its rollback",
            root.display()
        );
    }
    Ok(git
        .run(&["status", "--porcelain", "--untracked-files=all"])?
        .lines()
        .map(str::to_string)
        .collect())
}

/// The migration plan for `tools`, read from disk without writing.
pub fn plan(root: &Path, tools: &[Tool], today: &str) -> Result<Plan> {
    let mut tools = tools.to_vec();
    tools.sort();
    tools.dedup();
    if tools.is_empty() {
        bail!("pass --from openspec, speckit or superpowers");
    }
    let has_config = root.join(FILE).is_file();
    let config = if has_config {
        config::load(root)?
    } else {
        adopt::detect(root)?.config
    };
    let spec_root = root.join(&config.spec_root);
    let mut p = Plan {
        tools: tools.clone(),
        lines: Vec::new(),
        spec_root: spec_root.clone(),
        adopt: None,
        prefixes: config.id_prefixes.clone(),
        config_text: None,
        import: None,
        assign_ids: false,
        principles: None,
        remove_files: Vec::new(),
        remove_dirs: Vec::new(),
        prune: Vec::new(),
        settings: None,
        agents: Vec::new(),
    };
    let principles_path = spec_root.join("principles.md");
    // The principles text as it will be before the OpenSpec step: on disk, or imported.
    let mut principles_before = std::fs::read_to_string(&principles_path).ok();

    if tools.contains(&Tool::SpecKit) {
        let specify = root.join(".specify");
        let import = speckit::plan(root, &spec_root, &config.id_prefixes, today)?;
        if !specify.is_dir() && import.features.is_empty() {
            bail!("--from speckit: no .specify/ or specs/NNN-<name>/ folders found");
        }
        for f in &import.features {
            p.lines.push(format!(
                "import {} → {} ({}, {}, {}, {})",
                rel(&f.folder, root),
                f.name,
                if f.finished { "finished" } else { "open" },
                plural(f.requirements, "requirement"),
                plural(f.scenarios, "scenario"),
                plural(f.gaps.len(), "gap")
            ));
            for o in &f.outputs {
                p.lines
                    .push(format!("create {} (import)", rel(&o.path, root)));
            }
        }
        if let Some(o) = &import.principles {
            if let Content::Copy(src) = &o.content {
                p.lines.push(format!(
                    "create {} (from {})",
                    rel(&o.path, root),
                    rel(src, root)
                ));
                principles_before = Some(std::fs::read_to_string(src)?);
            }
        }
        p.import = Some(import);
    }

    if !has_config {
        p.lines.push(format!("create {FILE} (adopt)"));
        p.adopt = Some(config.clone());
    }
    // The local run ledger stays out of the migration commit (MIG-011).
    match config::ledger_ignore(root) {
        config::LedgerIgnore::Present => {}
        config::LedgerIgnore::Change => {
            p.lines.push("change .gitignore (ignore the ledger)".into())
        }
        config::LedgerIgnore::Create => {
            p.lines.push("create .gitignore (ignore the ledger)".into())
        }
    }

    if tools.contains(&Tool::OpenSpec) {
        if !spec_root.is_dir() {
            bail!("--from openspec: {} does not exist", rel(&spec_root, root));
        }
        p.assign_ids = true;
        // Short prefixes for capabilities without IDs, pinned before IDs are assigned (MIG-012).
        let pinned = ids::unmapped_prefixes(&spec_root, &config.id_prefixes)?;
        if !pinned.is_empty() {
            p.prefixes.extend(pinned.clone());
            if let Some(adopt) = &mut p.adopt {
                adopt.id_prefixes.extend(pinned.clone());
            } else {
                let path = root.join(FILE);
                let before = std::fs::read_to_string(&path)
                    .with_context(|| format!("cannot read {}", path.display()))?;
                let after = ids::add_prefix_lines(&before, &pinned);
                if !matches!(Config::parse(&after), Ok(c) if c.id_prefixes == p.prefixes) {
                    bail!(
                        "{FILE}: adding the ID prefixes did not give the expected `[ids.prefixes]` table; \
                         add these lines to it by hand:\n{}",
                        pinned
                            .iter()
                            .map(|(cap, prefix)| format!("{cap} = \"{prefix}\""))
                            .collect::<Vec<_>>()
                            .join("\n")
                    );
                }
                let n = pinned.len();
                p.lines.push(format!(
                    "change {FILE} ({n} ID {})",
                    if n == 1 { "prefix" } else { "prefixes" }
                ));
                p.config_text = Some(after);
            }
        }
        let mut per_file: BTreeMap<PathBuf, usize> = BTreeMap::new();
        for a in ids::plan(&spec_root, &p.prefixes)? {
            *per_file.entry(a.file).or_default() += 1;
        }
        for (file, n) in per_file {
            p.lines.push(format!(
                "change {} ({})",
                rel(&file, root),
                if n == 1 {
                    "1 ID".into()
                } else {
                    format!("{n} IDs")
                }
            ));
        }
        let yaml_path = spec_root.join("config.yaml");
        if let Ok(yaml) = std::fs::read_to_string(&yaml_path) {
            let text = match &principles_before {
                Some(before) => format!("{}\n\n{}", before.trim_end(), to_principles(&yaml, true)),
                None => to_principles(&yaml, false),
            };
            p.lines.push(format!(
                "{} {} (from {})",
                if principles_before.is_some() {
                    "change"
                } else {
                    "create"
                },
                rel(&principles_path, root),
                rel(&yaml_path, root)
            ));
            p.principles = Some((principles_path.clone(), text));
            p.lines.push(format!("remove {}", rel(&yaml_path, root)));
            p.remove_files.push(yaml_path);
        }
        for agent in agent_dirs(root) {
            for dir in sorted_entries(&agent.join("skills")) {
                let named = dir
                    .file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| n.starts_with("openspec-"));
                let file = dir.join("SKILL.md");
                if named && std::fs::read_to_string(&file).is_ok_and(|t| is_openspec_skill(&t)) {
                    p.lines
                        .push(format!("remove {} (OpenSpec skill)", rel(&file, root)));
                    p.prune.extend(parents(&file, root));
                    p.remove_files.push(file);
                }
            }
            for file in sorted_entries(&agent.join("commands").join("opsx")) {
                let md = file.extension().is_some_and(|e| e == "md");
                if md && std::fs::read_to_string(&file).is_ok_and(|t| is_openspec_command(&t)) {
                    p.lines
                        .push(format!("remove {} (OpenSpec command)", rel(&file, root)));
                    p.prune.extend(parents(&file, root));
                    p.remove_files.push(file);
                }
            }
            for file in sorted_entries(&agent.join("workflows")) {
                let opsx = file
                    .file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| n.starts_with("opsx-") && n.ends_with(".md"));
                if opsx && std::fs::read_to_string(&file).is_ok_and(|t| is_openspec_workflow(&t)) {
                    p.lines
                        .push(format!("remove {} (OpenSpec workflow)", rel(&file, root)));
                    p.prune.extend(parents(&file, root));
                    p.remove_files.push(file);
                }
            }
        }
    }

    if tools.contains(&Tool::SpecKit) {
        let specify = root.join(".specify");
        for manifest in sorted_entries(&specify.join("integrations")) {
            if !manifest
                .file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.ends_with(".manifest.json"))
            {
                continue;
            }
            let text = std::fs::read_to_string(&manifest)?;
            let v: serde_json::Value = serde_json::from_str(&text)
                .with_context(|| format!("{} is not valid JSON", manifest.display()))?;
            let Some(files) = v.get("files").and_then(|f| f.as_object()) else {
                continue;
            };
            for listed in files.keys() {
                if listed.starts_with(".specify/") || listed.contains("..") {
                    continue;
                }
                let file = root.join(listed);
                if file.is_file() {
                    p.lines.push(format!("remove {listed} (Spec Kit file)"));
                    p.prune.extend(parents(&file, root));
                    p.remove_files.push(file);
                }
            }
        }
        if specify.is_dir() {
            p.lines.push("remove .specify/".into());
            p.remove_dirs.push(specify);
        }
        for f in p.import.iter().flat_map(|i| &i.features) {
            p.lines.push(format!("remove {}/", rel(&f.folder, root)));
            p.remove_dirs.push(f.folder.clone());
            p.prune.extend(parents(&f.folder.join("x"), root));
        }
    }

    if tools.contains(&Tool::Superpowers) {
        let settings = root.join(".claude").join("settings.json");
        if let Ok(text) = std::fs::read_to_string(&settings) {
            let new = superpowers::settings_remove(&text)
                .with_context(|| format!("{} is not valid JSON", settings.display()))?;
            if new != text {
                p.lines.push(format!(
                    "change {} (remove Superpowers)",
                    rel(&settings, root)
                ));
                p.settings = Some((settings, new));
            }
        }
        let mut docs = Vec::new();
        files_under(&root.join("docs").join("superpowers"), &mut docs);
        for d in docs {
            p.lines.push(format!("review {} (kept)", rel(&d, root)));
        }
    }

    // Claude always, plus the agents the project has files for; no `AGENTS.md` fallback.
    let mut wanted = vec!["claude".to_string()];
    wanted.extend(agents::detect(root).into_iter().map(str::to_string));
    p.agents = agents::resolve(root, &wanted).0;
    for step in agents::plan(root, &p.agents, false)? {
        p.lines.push(match step.change {
            Change::Created(f) => format!("create {f} (adapter)"),
            Change::Updated(f) if f == ".claude/settings.json" => {
                let text = std::fs::read_to_string(root.join(&f)).unwrap_or_default();
                match sj_adapters::claude::kept_hooks(&text) {
                    0 => format!("change {f} (adapter)"),
                    n => format!(
                        "change {f} (adapter) (merged: {} kept)",
                        plural(n, "existing hook")
                    ),
                }
            }
            Change::Updated(f) => format!("change {f} (adapter)"),
            Change::Removed(f) => format!("remove {f} (adapter)"),
            Change::Kept(f) => format!("keep   {f} (hand-edited; the adapter leaves it)"),
        });
    }
    p.prune.sort_by(|a, b| {
        b.components()
            .count()
            .cmp(&a.components().count())
            .then(a.cmp(b))
    });
    p.prune.dedup();
    Ok(p)
}

fn write(path: &Path, text: &str) -> Result<()> {
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).with_context(|| format!("cannot create {}", dir.display()))?;
    }
    std::fs::write(path, text).with_context(|| format!("cannot write {}", path.display()))
}

/// Perform `plan`. Refuses (before touching anything) on a dirty tree or an import target
/// that already exists.
pub fn apply(root: &Path, plan: &Plan) -> Result<()> {
    let dirty = dirty(root)?;
    if !dirty.is_empty() {
        bail!(
            "the working tree has uncommitted changes; commit or stash them first:\n{}",
            dirty.join("\n")
        );
    }
    let git = Git::new(root);
    let start = git
        .run(&["rev-parse", "--verify", "--quiet", "HEAD"])
        .ok()
        .map(|s| s.trim().to_string());
    let (top, manifest) = undo_paths(&git)?;
    let prefix = git.run(&["rev-parse", "--show-prefix"])?.trim().to_string();
    let paths: Vec<String> = targets(root, plan)?
        .into_iter()
        .map(|p| format!("{prefix}{p}"))
        .collect();
    // `hash-object --stdin-paths` reads one path per line.
    if let Some(bad) = paths.iter().find(|p| p.contains(['\n', '\r'])) {
        bail!("cannot migrate {bad:?}: its name holds a line break; rename it first (nothing was changed)");
    }
    // The prior content of every file the plan may change or remove, stored as blobs.
    let before = hashes(&top, &paths, true)?;
    // A failed write may have changed files already, so record them; its error comes first.
    let written = write_plan(root, plan);
    let recorded = record_undo(&top, &manifest, start, &paths, &before);
    written.and(recorded)
}

/// Every file the plan may create, change or remove, relative to `root`, from the plan
/// itself rather than `git status`, so gitignored files count.
fn targets(root: &Path, plan: &Plan) -> Result<Vec<String>> {
    let mut out: Vec<PathBuf> = Vec::new();
    if let Some(import) = &plan.import {
        out.extend(import.outputs().map(|o| o.path.clone()));
    }
    if plan.adopt.is_some() || plan.config_text.is_some() {
        out.push(root.join(FILE));
    }
    out.push(root.join(".gitignore"));
    if plan.assign_ids {
        out.extend(
            ids::plan(&plan.spec_root, &plan.prefixes)?
                .into_iter()
                .map(|a| a.file),
        );
    }
    if let Some((path, _)) = &plan.principles {
        out.push(path.clone());
    }
    out.extend(plan.remove_files.iter().cloned());
    for d in &plan.remove_dirs {
        files_under(d, &mut out);
    }
    if let Some((path, _)) = &plan.settings {
        out.push(path.clone());
    }
    for step in agents::plan(root, &plan.agents, false)? {
        match step.change {
            Change::Created(f) | Change::Updated(f) | Change::Removed(f) => out.push(root.join(f)),
            Change::Kept(_) => {}
        }
    }
    let mut out: Vec<String> = out.iter().map(|p| rel(p, root)).collect();
    out.sort();
    out.dedup();
    Ok(out)
}

/// The undo manifest's name, inside the git directory.
pub const UNDO_FILE: &str = "sj-migrate-undo.json";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Action {
    Created,
    Changed,
    Removed,
}

#[derive(Serialize, Deserialize)]
struct UndoEntry {
    path: String,
    action: Action,
    /// The content hash after the write; `None` for a removed file.
    hash: Option<String>,
    /// The blob of the content before the write; `None` for a created file.
    blob: Option<String>,
}

#[derive(Serialize, Deserialize)]
struct Undo {
    /// The commit migrate started from; `None` in a repo without one.
    commit: Option<String>,
    files: Vec<UndoEntry>,
}

/// The repo's top level and the undo manifest's path.
fn undo_paths(git: &Git) -> Result<(PathBuf, PathBuf)> {
    let top = PathBuf::from(git.run(&["rev-parse", "--show-toplevel"])?.trim());
    let dir = PathBuf::from(git.run(&["rev-parse", "--absolute-git-dir"])?.trim());
    Ok((top, dir.join(UNDO_FILE)))
}

/// Git's hash of each of `paths` (relative to the top level) as it is now; `None` when
/// missing. `store` also writes each file's blob to the object database. The paths go to
/// git on stdin, so any number of them stays under the command-line limit.
fn hashes(top: &Path, paths: &[String], store: bool) -> Result<Vec<Option<String>>> {
    let present: Vec<&str> = paths
        .iter()
        .map(String::as_str)
        .filter(|p| top.join(p).is_file())
        .collect();
    let mut found = BTreeMap::new();
    if !present.is_empty() {
        let mut args = vec!["hash-object"];
        if store {
            args.push("-w");
        }
        args.push("--stdin-paths");
        let input: String = present.iter().map(|p| format!("{p}\n")).collect();
        let out = Git::new(top).run_stdin(&args, &input)?;
        for (p, h) in present.iter().zip(out.lines()) {
            found.insert(*p, h.to_string());
        }
    }
    Ok(paths
        .iter()
        .map(|p| found.get(p.as_str()).cloned())
        .collect())
}

/// Write the undo manifest for every path of `paths` the write created, changed or removed,
/// given each one's blob from `before`. Paths `git status` lists that the plan didn't name
/// are recorded too: the tree was clean before, so they are migrate's, and their prior
/// content is the start commit's.
fn record_undo(
    top: &Path,
    manifest: &Path,
    commit: Option<String>,
    paths: &[String],
    before: &[Option<String>],
) -> Result<()> {
    let git = Git::new(top);
    let mut paths = paths.to_vec();
    let mut before = before.to_vec();
    let status = git.run(&["status", "--porcelain", "-z", "--untracked-files=all"])?;
    let extra: Vec<String> = status
        .split('\0')
        .filter(|e| e.len() > 3)
        .map(|e| e[3..].to_string())
        .filter(|p| !paths.contains(p))
        .collect();
    let mut unhashable = Vec::new();
    if !extra.is_empty() {
        let head = match &commit {
            Some(c) => head_blobs(&git, c)?,
            None => BTreeMap::new(),
        };
        for p in extra {
            if p.contains(['\n', '\r']) {
                unhashable.push(p);
                continue;
            }
            before.push(head.get(&p).cloned());
            paths.push(p);
        }
    }
    let after = hashes(top, &paths, false)?;
    let files: Vec<UndoEntry> = paths
        .iter()
        .zip(&before)
        .zip(after)
        .filter_map(|((path, blob), hash)| {
            let action = match (blob, &hash) {
                (None, Some(_)) => Action::Created,
                (Some(_), None) => Action::Removed,
                (Some(b), Some(h)) if b != h => Action::Changed,
                _ => return None,
            };
            Some(UndoEntry {
                path: path.clone(),
                action,
                hash,
                blob: blob.clone(),
            })
        })
        .collect();
    if !files.is_empty() {
        let json = serde_json::to_string_pretty(&Undo { commit, files })?;
        std::fs::write(manifest, json + "\n")
            .with_context(|| format!("cannot write {}", manifest.display()))?;
    }
    if !unhashable.is_empty() {
        bail!(
            "undo can't record these files, whose names hold a line break; restore or remove them by hand (e.g. `git restore <file>` for a tracked file):\n{}",
            unhashable.join("\n")
        );
    }
    Ok(())
}

/// The blob of every file in `commit`'s tree, by path from the top level.
fn head_blobs(git: &Git, commit: &str) -> Result<BTreeMap<String, String>> {
    let tree = git.run(&["ls-tree", "-r", "-z", "--full-tree", commit])?;
    Ok(tree
        .split('\0')
        .filter_map(|e| {
            let (meta, path) = e.split_once('\t')?;
            let mut f = meta.split(' ');
            let (_mode, kind, id) = (f.next()?, f.next()?, f.next()?);
            (kind == "blob").then(|| (path.to_string(), id.to_string()))
        })
        .collect())
}

/// What [`undo`] put back.
pub struct Undone {
    pub restored: usize,
    pub deleted: usize,
}

/// Put back what the last `--write` touched, from its undo manifest. Refuses, changing
/// nothing, when a recorded file no longer has the content migrate left.
pub fn undo(root: &Path) -> Result<Undone> {
    let git = Git::new(root);
    if !git.is_repo() {
        bail!("{} is not a git work tree", root.display());
    }
    let (top, manifest) = undo_paths(&git)?;
    let Ok(text) = std::fs::read_to_string(&manifest) else {
        bail!("nothing to undo: no {UNDO_FILE} in the git directory");
    };
    let undo: Undo = serde_json::from_str(&text)
        .with_context(|| format!("{} is not a valid undo manifest", manifest.display()))?;
    let paths: Vec<String> = undo.files.iter().map(|f| f.path.clone()).collect();
    let edited: Vec<&str> = undo
        .files
        .iter()
        .zip(hashes(&top, &paths, false)?)
        .filter(|(f, now)| f.hash != *now)
        .map(|(f, _)| f.path.as_str())
        .collect();
    if !edited.is_empty() {
        bail!(
            "these files changed since the migration (nothing was changed); restore them to \
             the content migrate wrote (e.g. `git restore <file>` for a tracked file) and \
             run `sj migrate --undo` again:\n{}",
            edited.join("\n")
        );
    }
    let mut old = Vec::new();
    for f in undo.files.iter().filter(|f| f.action != Action::Created) {
        let Some(blob) = &f.blob else {
            bail!("the undo manifest records no prior content for {}", f.path);
        };
        // `--filters` applies the working-tree conversions (eol, smudge) for `--path`, so
        // the file comes back with the bytes it had on disk, CRLF endings included.
        let out = std::process::Command::new("git")
            .args(["cat-file", "--filters", &format!("--path={}", f.path), blob])
            .current_dir(&top)
            .output()
            .context("running git (is it installed and on PATH?)")?;
        if !out.status.success() {
            bail!(
                "git cat-file --filters --path={} {blob} failed: {}",
                f.path,
                String::from_utf8_lossy(&out.stderr).trim()
            );
        }
        old.push((f, out.stdout));
    }
    let mut done = Undone {
        restored: 0,
        deleted: 0,
    };
    for (f, content) in old {
        let path = top.join(&f.path);
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir)
                .with_context(|| format!("cannot create {}", dir.display()))?;
        }
        std::fs::write(&path, content)
            .with_context(|| format!("cannot write {}", path.display()))?;
        done.restored += 1;
    }
    for f in undo.files.iter().filter(|f| f.action == Action::Created) {
        let path = top.join(&f.path);
        std::fs::remove_file(&path).with_context(|| format!("cannot remove {}", path.display()))?;
        done.deleted += 1;
        // Folders left empty by the created files go too; never one holding anything else.
        for dir in path.ancestors().skip(1) {
            if dir == top || std::fs::remove_dir(dir).is_err() {
                break;
            }
        }
    }
    std::fs::remove_file(&manifest)
        .with_context(|| format!("cannot remove {}", manifest.display()))?;
    Ok(done)
}

/// The writes of [`apply`], without its clean-tree check.
fn write_plan(root: &Path, plan: &Plan) -> Result<()> {
    if let Some(import) = &plan.import {
        let conflicts = import.conflicts();
        if !conflicts.is_empty() {
            bail!(
                "the Spec Kit import would overwrite {}; nothing was changed",
                conflicts
                    .iter()
                    .map(|c| rel(c, root))
                    .collect::<Vec<_>>()
                    .join(", ")
            );
        }
        speckit::write(import, false)?;
    }
    if let Some(config) = &plan.adopt {
        write(&root.join(FILE), &config.to_toml())?;
    }
    if let Some(text) = &plan.config_text {
        write(&root.join(FILE), text)?;
    }
    config::ignore_ledger(root)?;
    if plan.assign_ids {
        ids::write(&ids::plan(&plan.spec_root, &plan.prefixes)?)?;
    }
    if let Some((path, text)) = &plan.principles {
        write(path, text)?;
    }
    for f in &plan.remove_files {
        std::fs::remove_file(f).with_context(|| format!("cannot remove {}", f.display()))?;
    }
    for d in &plan.remove_dirs {
        std::fs::remove_dir_all(d).with_context(|| format!("cannot remove {}", d.display()))?;
    }
    for d in &plan.prune {
        if std::fs::read_dir(d).is_ok_and(|mut e| e.next().is_none()) {
            std::fs::remove_dir(d).with_context(|| format!("cannot remove {}", d.display()))?;
        }
    }
    if let Some((path, text)) = &plan.settings {
        write(path, text)?;
    }
    // Planned again now: the Superpowers step above may have changed `.claude/settings.json`.
    sj_adapters::plan::apply(agents::plan(root, &plan.agents, false)?)?;
    Ok(())
}

/// The files a project's migration may read: every file but those `.gitignore` excludes and
/// `.git/`, relative to `root`. Ignored files stay out of the copy [`diff`] plans on, since
/// folders like `target/` can be huge; a plan that reads an ignored file (say a gitignored
/// `.claude/settings.json`) may then preview differently from the real `--write`.
fn project_files(root: &Path) -> Vec<PathBuf> {
    let mut out: Vec<PathBuf> = ignore::WalkBuilder::new(root)
        .hidden(false)
        .require_git(false)
        .filter_entry(|e| e.file_name() != ".git")
        .build()
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_some_and(|t| t.is_file()))
        .filter_map(|e| e.path().strip_prefix(root).ok().map(Path::to_path_buf))
        .collect();
    out.sort();
    out
}

/// A unified diff of every file the migration would create or change, without writing to
/// `root`: the plan is carried out on a copy of the project and the copy compared with it.
pub fn diff(root: &Path, tools: &[Tool], today: &str) -> Result<String> {
    let tmp = tempfile::tempdir().context("creating a temporary copy of the project")?;
    let copy = tmp.path();
    for f in project_files(root) {
        let dest = copy.join(&f);
        if let Some(dir) = dest.parent() {
            std::fs::create_dir_all(dir)
                .with_context(|| format!("cannot create {}", dir.display()))?;
        }
        std::fs::copy(root.join(&f), &dest)
            .with_context(|| format!("cannot copy {}", f.display()))?;
    }
    write_plan(copy, &plan(copy, tools, today)?)?;
    let mut out = String::new();
    for f in project_files(copy) {
        let new = std::fs::read(copy.join(&f))?;
        let old = std::fs::read(root.join(&f)).unwrap_or_default();
        if new == old {
            continue;
        }
        let (Ok(old), Ok(new)) = (String::from_utf8(old), String::from_utf8(new)) else {
            continue;
        };
        out.push_str(&crate::linediff::unified(
            &rel(&f, Path::new("")),
            &old,
            &new,
        ));
    }
    Ok(out)
}

/// The checks after a write, and what git sees.
pub struct Finish {
    pub doctor: Vec<String>,
    pub validate: Report,
    pub created: usize,
    pub changed: usize,
    pub removed: usize,
}

impl Finish {
    pub fn is_clean(&self) -> bool {
        self.doctor.is_empty() && self.validate.errors.is_empty()
    }
}

pub fn finish(root: &Path, plan: &Plan) -> Result<Finish> {
    let doctor = doctor::check(root);
    let validate = validate::validate(&plan.spec_root, None)?;
    let (mut created, mut changed, mut removed) = (0, 0, 0);
    for l in dirty(root)? {
        match l.get(..2) {
            Some("??") | Some("A ") => created += 1,
            Some(s) if s.contains('D') => removed += 1,
            _ => changed += 1,
        }
    }
    Ok(Finish {
        doctor,
        validate,
        created,
        changed,
        removed,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn git(dir: &Path, args: &[&str]) {
        let ok = std::process::Command::new("git")
            .args([
                "-c",
                "user.name=t",
                "-c",
                "user.email=t@t",
                "-c",
                "commit.gpgsign=false",
            ])
            .args(args)
            .current_dir(dir)
            .status()
            .unwrap()
            .success();
        assert!(ok, "git {args:?}");
    }

    /// Files the write touched that the plan's list missed are still recorded, from
    /// `git status`, with the start commit's content, and undo puts them back.
    #[test]
    fn undo_records_files_only_git_status_lists() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git(root, &["init", "-q"]);
        // Git for Windows defaults to `core.autocrlf=true`, which would restore these LF files
        // as CRLF, the way a checkout writes them. Line endings have their own test
        // (`undo_restores_crlf_line_endings`).
        git(root, &["config", "core.autocrlf", "false"]);
        std::fs::write(root.join("kept.txt"), "old\n").unwrap();
        std::fs::write(root.join("gone.txt"), "gone\n").unwrap();
        git(root, &["add", "."]);
        git(root, &["commit", "-qm", "start"]);
        let g = Git::new(root);
        let commit = g.run(&["rev-parse", "HEAD"]).unwrap().trim().to_string();
        let (top, manifest) = undo_paths(&g).unwrap();

        // A write the plan didn't list: one change, one removal, one new file.
        std::fs::write(root.join("kept.txt"), "new\n").unwrap();
        std::fs::remove_file(root.join("gone.txt")).unwrap();
        std::fs::write(root.join("made.txt"), "made\n").unwrap();
        record_undo(&top, &manifest, Some(commit), &[], &[]).unwrap();

        let undo: Undo =
            serde_json::from_str(&std::fs::read_to_string(&manifest).unwrap()).unwrap();
        let actions: Vec<(&str, Action, bool)> = undo
            .files
            .iter()
            .map(|f| (f.path.as_str(), f.action, f.blob.is_some()))
            .collect();
        assert_eq!(
            actions,
            [
                ("gone.txt", Action::Removed, true),
                ("kept.txt", Action::Changed, true),
                ("made.txt", Action::Created, false),
            ]
        );

        super::undo(root).unwrap();
        assert_eq!(
            std::fs::read_to_string(root.join("kept.txt")).unwrap(),
            "old\n"
        );
        assert_eq!(
            std::fs::read_to_string(root.join("gone.txt")).unwrap(),
            "gone\n"
        );
        assert!(!root.join("made.txt").exists());
    }
}
